INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_verbal', '慣用句', NULL, '次の慣用句の意味として、最も適切なものはどれか。

